mapper.select:
SELECT e.datasource_id AS datasourceId, e.job_id AS jobId, e.id AS jobExecutionId, e.name AS executionName, e.table_name AS tableName, r.column_name AS columnName, r.metric_name AS metricName, r.metric_type AS metricType, r.actual_value AS actualValue, r.state AS state, e.error_data_storage_type AS errorDataStorageType, e.error_data_storage_parameter AS errorDataStorageParameter, e.error_data_file_name AS errorDataFileName, j.name AS jobName, j.parameter AS jobParameter, j.rule_id AS ruleId FROM dv_job_execution e INNER JOIN ( SELECT datasource_id, job_id, IFNULL(table_name, '') AS table_name, MAX(id) AS max_id FROM dv_job_execution WHERE datasource_id IN
#{id}
AND start_time < #{rangeEnd} GROUP BY datasource_id, job_id, IFNULL(table_name, '') ) latest ON e.id = latest.max_id INNER JOIN dv_job_execution_result r ON r.job_execution_id = e.id LEFT JOIN dv_job j ON j.id = e.job_id
AND j.tag_name = #{businessTag}
ORDER BY e.datasource_id, e.table_name, e.job_id, e.id DESC
